import {Search,Location,Calendar,Wallet,Right} from '@element-plus/icons-vue'
import api from '../services/api.js'
import SectionTitle from '../components/SectionTitle.vue';import GuideCard from '../components/GuideCard.vue';import DestinationCard from '../components/DestinationCard.vue'
const router=useRouter(),loading=ref(true),error=ref(''),keyword=ref(''),data=ref({banners:[],destinations:[],featuredGuides:[],routes:[],topics:[],creators:[],latestGuides:[]})
