<template><div class="home"><section class="hero"><Swiper :modules="[Navigation,Pagination,Autoplay]" :slides-per-view="1" :loop="true" :autoplay="{delay:6000,disableOnInteraction:false}" navigation pagination><SwiperSlide v-for="banner in (data.banners.length?data.banners:fallbackBanners)" :key="banner.id"><div class="hero-slide" :style="{backgroundImage:`linear-gradient(90deg,rgba(7,37,44,.72),rgba(7,37,44,.05)),url(${banner.imageUrl})`}"><div class="container hero-copy"><span class="hero-note">THIS SEASON · 本季灵感</span><h1>{{banner.title}}</h1><p>{{banner.subtitle}}</p><button @click="router.push(banner.linkUrl||'/destinations')">看看这段旅程 <el-icon><Right/></el-icon></button></div></div></SwiperSlide></Swiper><div class="hero-search"><div><el-icon><Search/></el-icon><input v-model="keyword" placeholder="想去哪里？搜索目的地、攻略或路线" @keyup.enter="search"><button @click="search">开始探索</button></div><p><b>大家在搜</b><a v-for="word in ['成都三天两夜','大理环洱海','北京秋季','学生党厦门']" :key="word" @click="keyword=word;search()">{{word}}</a></p></div></section><div v-if="error" class="api-note">后端暂未连接，正在展示本地预览素材；启动后端后会自动读取完整演示数据。</div>
