<section class="section"><div class="container"><SectionTitle eyebrow="TRAVEL CREATORS" title="跟着熟悉远方的人" subtitle="他们把真实经验写下来，让下一次出发少一点慌张"/><div class="creator-row"><router-link v-for="creator in data.creators" :key="creator.id" :to="`/creator/${creator.id}`" class="creator-card"><img :src="creator.avatar" :alt="creator.nickname"><h3>{{creator.nickname}}</h3><p>{{creator.bio}}</p><div><span><b>{{creator.guideCount}}</b> 攻略</span><span><b>{{Number(creator.receivedLikes).toLocaleString()}}</b> 获赞</span></div></router-link></div></div></section>
